<?php
$filters = $filters ?? ['search' => '', 'status' => '', 'source_type' => '', 'page_size' => 15];
$permissions = $permissions ?? session('permissions') ?? [];
$can = static fn (string $permission): bool => in_array($permission, $permissions, true);
$page = $pager?->getCurrentPage('patients') ?? 1;
$total = $pager?->getTotal('patients') ?? count($patients ?? []);
$formatDate = static function ($value): string { if (empty($value)) return 'Unknown'; $timestamp = strtotime((string) $value); return $timestamp ? date('d-m-Y', $timestamp) : 'Unknown'; };
$age = static function ($value): string { if (empty($value)) return 'Unknown'; try { return (string) (new DateTimeImmutable((string) $value))->diff(new DateTimeImmutable('today'))->y; } catch (Throwable $e) { return 'Unknown'; } };
?>
